function validateWatchlist(items){if(!Array.isArray(items)||items.length>50)return 'В списке может быть не более 50 товаров.';for(const item of items){if(!item.name?.trim())return 'Укажите название каждого товара.';if(!validOzonProductUrl(item.url))return 'Ссылка должна вести на товар https://ozon.ru/product/…';if(item.matchStatus==='confirmed'&&(!item.matchNotes?.trim()||!Number.isInteger(item.unitCount)||item.unitCount<1))return 'Для проверенного товара укажите упаковку и пояснение сопоставимости.'}return ''}
function scenarioSelection(item,terms){return terms?{title:'Сценарии по вашим условиям',scenarios:item?.commercialPlan?.scenarios}:{title:'Сценарии по фактическим расходам',scenarios:item?.advisory?.scenarios}}
function createDialogContext(scope,generation){return {storeId:String(scope?.storeId||''),productId:String(scope?.productId||''),revision:String(scope?.revision||'0'),generation,submission:null}}
