function watchProductId(value){try{const url=new URL(value);return url.protocol==='https:'&&['ozon.ru','www.ozon.ru'].includes(url.hostname)&&!url.username&&!url.password&&!url.port?/^\/product\/(?:[^/]*-)?([0-9]+)\/?$/.exec(url.pathname)?.[1]||null:null}catch{return null}}
function watchCompetitorInput(value,original){const currentId=watchProductId(value?.url),sameProduct=currentId!==null&&currentId===watchProductId(original?.url);return {name:String(value?.name||'').trim(),url:String(value?.url||'').trim(),matchStatus:value?.matchStatus==='confirmed'?'confirmed':'candidate',matchNotes:String(value?.matchNotes||'').trim(),unitCount:positiveInt(value?.unitCount,true),source:'ozon_seller_analytics',metrics:sameProduct&&original.metrics?structuredClone(original.metrics):null}}
const exported={LIMIT,numeric,money,count,percent,safeItems,buildListParams,moscowLocalValue,moscowInputToIso,validOzonProductUrl,positiveInt,isCurrentSelection,normalizeScenarios,buildEvidencePayload,validateWatchlist,economicsUsable,sumKnown,scenarioSelection,createDialogContext,stableSubmission,watchCompetitorInput};
