if(!root?.document)return;
const document=root.document,$=id=>document.getElementById(id),form=$('growth-filters'),list=$('growth-list'),detail=$('growth-detail'),notice=$('growth-notice');
const state={storeId:'',items:[],total:0,offset:0,payload:null,selected:null,listRequest:0,evidenceRequest:0,marketRequest:0,watchRequest:0,controller:null,market:null,watchlist:null,evidenceContext:null,watchContext:null,dialogGeneration:0};
const el=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=String(text);return node};
async function api(url,options={}){const response=await fetch(url,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});let body;try{body=await response.json()}catch{throw new Error('Сервер вернул неполный ответ.')}if(!response.ok)throw new Error(body?.error||body?.message||('Ошибка '+response.status));return body}
function dateTime(value){if(!value)return 'время не указано';const date=new Date(value);return Number.isNaN(date.getTime())?'время не указано':date.toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'})}
function announce(message,error=false){notice.textContent=message||'';notice.hidden=!message;notice.classList.toggle('is-error',error)}
function filters(){return {store:form.elements.store.value||state.storeId,objective:form.elements.objective.value||'profit_volume',search:form.elements.search.value.trim(),from:form.elements.from.value,to:form.elements.to.value}}
function replaceStores(stores){const select=$('growth-store'),wanted=state.storeId||select.value;select.replaceChildren(new Option('Все магазины',''));const seen=new Set;for(const item of Array.isArray(stores)?stores:[]){const id=String(item?.id||'');if(!id||seen.has(id))continue;seen.add(id);select.append(new Option(item.name||id,id))}select.value=seen.has(String(wanted))?String(wanted):'';state.storeId=select.value}
function updateLinks(){const store=state.selected?.product?.storeId||state.storeId,suffix=store?'?store='+encodeURIComponent(store):'';$('growth-link-control').href='/ad-control.html'+suffix;$('growth-link-ads').href='/ads.html'+suffix;$('growth-link-prices').href='/prices.html'+suffix}
function statusClass(status){const text=String(status||'').toLowerCase();return text.includes('block')||text.includes('unavailable')?'blocked':text.includes('missing')||text.includes('partial')||text.includes('conditional')?'warning':''}
const statusLabels={data_needed:'Нужны данные',ready:'Готово к оценке',conditional:'При условиях',unavailable:'Недоступно',blocked:'Заблокировано',observe:'Наблюдаем'};
