function sumKnown(values){const known=values.map(numeric).filter(value=>value!==null);return {value:known.length?known.reduce((sum,value)=>sum+value,0):null,known:known.length}}
function renderKpis(){const spend=sumKnown(state.items.map(item=>item?.advertising?.spend)),orders=sumKnown(state.items.map(item=>item?.advertising?.orders)),units=sumKnown(state.items.map(item=>item?.analysisBasis?.units)),complete=state.items.filter(economicsUsable).length;$('growth-kpis').replaceChildren(metricCard('Товаров',count(state.items.length),'Только на этой странице'),metricCard('Расходы на рекламу',money(spend.value),`${spend.known} из ${state.items.length} значений на этой странице`),metricCard('Заказы / единицы',count(orders.value)+' / '+count(units.value),`${orders.known} / ${units.known} известных значений`),metricCard('Экономика пригодна',complete+' из '+state.items.length,'Полные финансы и актуальная себестоимость'))}
function productMeta(item){return [item?.product?.storeName,item?.product?.sku&&('SKU '+item.product.sku),item?.product?.offerId&&('Артикул '+item.product.offerId)].filter(Boolean).join(' · ')}
function cell(label,value,className=''){if(label==='Прибыль')label='Вклад на единицу';const box=el('div','growth-cell');box.append(el('span','',label),el('strong',className,value));return box}
