function renderPager(){const first=state.total?state.offset+1:0,last=Math.min(state.total,state.offset+state.items.length);$('growth-page-info').textContent=`Показано ${count(first)}–${count(last)} из ${count(state.total)}`;$('growth-page-count').textContent=state.items.length+' товаров на этой странице';$('growth-prev').disabled=state.offset<=0;$('growth-next').disabled=state.offset+LIMIT>=state.total}
function renderTermsSummary(){const node=$('growth-terms-summary'),terms=state.payload?.commercialTerms?.terms;node.replaceChildren();if(!terms){node.append(el('strong','','Условия расчёта:'),el('span','','не подтверждены'));return}node.append(el('strong','','Условия расчёта:'),el('span','',`комиссия ${percent(terms.commissionPct)}`),el('span','',`резерв на рекламу ${percent(terms.advertisingPct)}`),el('span','',terms.priceBasis==='seller_price'?'база — цена продавца':'база — '+String(terms.priceBasis||'не указана')))}
