function renderTerms(container,item){const block=section('План по вашим условиям');const terms=state.payload?.commercialTerms?.terms;if(!terms){block.append(el('p','','Индивидуальные условия пока не подтверждены для расчёта.'));container.append(block);return}const grid=el('div','growth-facts');grid.append(fact('Комиссия',percent(terms.commissionPct),'Из условий расчёта'),fact('Резерв на рекламу',percent(terms.advertisingPct),'Из условий расчёта'),fact('База процентов',terms.priceBasis==='seller_price'?'Цена продавца':String(terms.priceBasis||'Не указана')),fact('Применение',terms.application==='planning_reserve'?'Плановый резерв':String(terms.application||'Не указано')));block.append(grid);const plan=item?.commercialPlan;if(!plan||plan.status==='unavailable'){block.append(el('p','',missingText(plan?.missing)||'План по вашим условиям пока не рассчитан.'));container.append(block);return}const retained=numeric(plan.retainedRevenue),unitCost=numeric(plan.unitCost),remainder=retained!==null&&unitCost!==null?retained-unitCost:null,planGrid=el('div','growth-facts');planGrid.append(fact('Выручка после процентов',money(retained),'План, не факт'),fact('Себестоимость',money(unitCost),'На единицу'),fact('Остаток до прочих расходов',money(remainder),'Это не прибыль'),fact('Прочие затраты',money(plan.otherCostsPerUnit),'На единицу'),fact('Полный плановый вклад',plan.status==='complete'?money(plan.contributionPerUnit):'—','На единицу, не обещание прибыли'),fact('Минимальная цена',money(plan.minPrice),'По доступным условиям'));block.append(planGrid);const missing=missingText(plan.missing);if(missing)block.append(el('p','',`Для полного плана не хватает: ${missing}.`));container.append(block)}
function renderScenarios(container,item){const selection=scenarioSelection(item,state.payload?.commercialTerms?.terms),block=section(selection.title),wrapper=el('div','growth-scenarios');for(const scenario of normalizeScenarios(selection.scenarios)){const card=el('article','growth-scenario'),head=document.createElement('header');head.append(el('h4','',scenario.label||scenario.id||'Сценарий'),el('span','',scenario.status==='conditional'?'При условиях':'Недоступен'));card.append(head,el('p','',scenario.summary||'Описание не получено.'));const metrics=el('div','scenario-metrics');for(const metric of Array.isArray(scenario.metrics)?scenario.metrics:[]){const formatted=metric.unit==='RUB'?money(metric.value):metric.unit==='percent'?percent(metric.value):metric.unit==='units'?count(metric.value)+' ед.':count(metric.value);metrics.append(el('span','',`${metric.label}: ${formatted}`))}if(metrics.children.length)card.append(metrics);if(Array.isArray(scenario.assumptions)&&scenario.assumptions.length)card.append(el('p','',`Условия: ${scenario.assumptions.join('; ')}`));wrapper.append(card)}block.append(wrapper);container.append(block)}
function evidenceList(item){const block=section('Наблюдения рынка');const evidence=item?.marketEvidence,observations=Array.isArray(evidence?.observations)?evidence.observations:[];const ul=el('ul','growth-observations');if(!observations.length)ul.append(el('li','','Локальных наблюдений пока нет.'));for(const observation of observations.slice(0,5)){const competitors=Array.isArray(observation.competitors)?observation.competitors.length:0;ul.append(el('li','',`${dateTime(observation.observedAt)} · ${observation.region||'регион не указан'} · «${observation.query||'запрос не указан'}» · аналогов: ${competitors}${observation.ownPosition?' · ваша позиция '+observation.ownPosition:''}`))}block.append(ul);return block}
function marketPrice(value){const amount=numeric(value?.minimumPrice);if(amount===null)return '—';return count(amount)+' '+(value?.currency||'валюта не указана')}
function renderMarket(container){const block=section('Индекс цены Ozon');block.append(el('p','','Агрегированный ориентир из официального Ozon Seller API. Это не список всех конкурентов и не сравнение с вашей ценой.'));if(state.market){const index=state.market.priceIndex||{},grid=el('div','growth-market-index');for(const [label,value] of [['Ozon',index.ozon],['Внешний рынок',index.external],['Свои площадки',index.ownMarketplaces]])grid.append(fact(label,value?`${marketPrice(value)} · индекс ${count(value.index)}`:'—'));block.append(grid,el('p','',`${state.market.message||''} Получено: ${dateTime(state.market.observedAt)}.`))}const button=el('button','growth-button secondary','Проверить индекс цены Ozon');button.type='button';button.addEventListener('click',loadMarket);block.append(button);container.append(block)}
function renderWatchlist(container){const block=section('Наши конкуренты');const competitors=Array.isArray(state.watchlist?.competitors)?state.watchlist.competitors:[];const listNode=el('ul','growth-observations');if(!competitors.length)listNode.append(el('li','','Список сравнения пока пуст.'));for(const competitor of competitors.slice(0,50)){let text=`${competitor.name||'Без названия'} · ${competitor.matchStatus==='confirmed'?'проверен':'кандидат'}`;const metrics=competitor.metrics;if(metrics)text+=` · средняя цена ${money(metrics.averagePrice)} / заказы ${count(metrics.orderedUnits)} / ДРР ${percent(metrics.drrPct)} за ${metrics.periodFrom||'—'}—${metrics.periodTo||'—'}`;listNode.append(el('li','',text))}block.append(listNode);const query=state.selected?.product?.name||'';const copy=el('div','copy-query');copy.append(el('code','',query||'Название товара не указано'));const copyButton=el('button','','Копировать запрос');copyButton.type='button';copyButton.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(query);copyButton.textContent='Скопировано'}catch{copyButton.textContent='Не удалось'}});copy.append(copyButton);block.append(copy);const actions=el('div','growth-detail-actions'),open=el('button','','Редактировать список');open.type='button';open.addEventListener('click',openWatchlist);const external=el('a','','Найти конкурентов в Ozon');external.href='https://seller.ozon.ru/app/analytics/competitors/ozon-bestsellers';external.target='_blank';external.rel='noopener noreferrer';actions.append(open,external);block.append(actions);container.append(block)}
function renderDetail(){const item=state.selected;if(!item){detail.innerHTML='<div class="growth-detail-empty"><h2 id="growth-detail-title">Решение по товару</h2><p>Выберите товар, чтобы увидеть четыре сценария, основания решения и недостающие данные.</p></div>';return}detail.replaceChildren();const head=el('div','growth-detail-head');const title=el('h2','',item.product?.name||'Товар');title.id='growth-detail-title';head.append(title,el('p','',`${productMeta(item)||'Идентификаторы не указаны'} · данные цены на ${dateTime(item.price?.observedAt)}`));detail.append(head);const advisory=el('section','growth-advisory');advisory.append(el('span','growth-status '+statusClass(item.advisory?.status),statusLabel(item.advisory?.status)),el('h3','',item.advisory?.title||'Решение не рассчитано'),el('p','',item.advisory?.summary||'Обоснование пока не получено.'));const actions=el('div','growth-detail-actions'),observe=el('button','','Добавить наблюдение');observe.type='button';observe.addEventListener('click',openEvidence);actions.append(observe);advisory.append(actions);detail.append(advisory);const facts=el('div','growth-facts');facts.append(fact('Цена продавца',money(item.price?.sellerPrice)),fact('Цена покупателя',money(item.price?.customerPrice)),fact('Остаток',numeric(item.stock?.quantity)===null?'—':count(item.stock?.quantity)+' ед.'),fact('Расходы рекламы',money(item.advertising?.spend)),fact('Заказы рекламы',count(item.advertising?.orders)),fact('Прибыль',contribution(item),economicsUsable(item)?'На реализованную единицу':'Полнота финансов и актуальность себестоимости не подтверждены'));detail.append(facts);renderTerms(detail,item);renderScenarios(detail,item);renderWatchlist(detail);renderMarket(detail);const signals=section('Почему такое решение'),signalsList=el('ul','growth-signals');for(const signal of Array.isArray(item.advisory?.signals)?item.advisory.signals:[])signalsList.append(el('li','',signal.text||signal.kind));if(!signalsList.children.length)signalsList.append(el('li','','Сигналы не получены.'));signals.append(signalsList);detail.append(signals);const missing=section('Чего не хватает'),missingList=el('ul','growth-missing');for(const evidence of Array.isArray(item.advisory?.missingEvidence)?item.advisory.missingEvidence:[])missingList.append(el('li','',evidence.text||evidence.code));if(!missingList.children.length)missingList.append(el('li','','Обязательных пропусков не указано.'));missing.append(missingList);detail.append(missing,evidenceList(item));const rawCoverage=item.advisory?.coverage,coverage=typeof rawCoverage==='string'?rawCoverage:rawCoverage?.message||state.payload?.coverage?.message||'Мониторинг всех конкурентов не подключён.';detail.append(el('p','growth-coverage',`${coverage} Позиция зависит от запроса, региона и времени; гарантий результата нет.`))}
async function selectItem(item){state.selected=item;state.market=null;state.watchlist=item.watchlist||null;updateLinks();renderList();renderDetail();await Promise.allSettled([loadEvidence(item),loadWatchlist(item)])}
async function loadEvidence(item){const storeId=String(item?.product?.storeId||''),productId=String(item?.product?.id||'');if(!storeId||!productId)return;const request=++state.evidenceRequest;try{const result=await api(`/api/growth/evidence?store=${encodeURIComponent(storeId)}&product=${encodeURIComponent(productId)}`);if(request!==state.evidenceRequest||!isCurrentSelection(state,storeId,productId))return;item.marketEvidence=result;renderDetail()}catch{if(request===state.evidenceRequest&&isCurrentSelection(state,storeId,productId))renderDetail()}}
async function loadWatchlist(item=state.selected){const storeId=String(item?.product?.storeId||''),productId=String(item?.product?.id||'');if(!storeId||!productId)return;const request=++state.watchRequest;try{const result=await api(`/api/growth/watchlist?store=${encodeURIComponent(storeId)}&product=${encodeURIComponent(productId)}`);if(request!==state.watchRequest||!isCurrentSelection(state,storeId,productId))return;state.watchlist=result;renderDetail()}catch{if(request===state.watchRequest&&isCurrentSelection(state,storeId,productId))renderDetail()}}
async function loadMarket(){const item=state.selected,storeId=String(item?.product?.storeId||''),productId=String(item?.product?.id||'');if(!storeId||!productId)return;const request=++state.marketRequest;announce('Проверяем доступный индекс цены Ozon…');try{const result=await api(`/api/growth/market?store=${encodeURIComponent(storeId)}&product=${encodeURIComponent(productId)}`);if(request!==state.marketRequest||!isCurrentSelection(state,storeId,productId))return;state.market=result;announce('Индекс цены Ozon обновлён.');renderDetail()}catch(error){if(request===state.marketRequest&&isCurrentSelection(state,storeId,productId))announce('Не удалось получить индекс Ozon: '+error.message,true)}}
async function loadList({preserveProductId=''}={}){state.controller?.abort();const controller=new AbortController;state.controller=controller;const request=++state.listRequest,selectedId=preserveProductId||state.selected?.product?.id||'';$('growth-refresh').disabled=true;announce('');const requestedFilters=filters();try{const payload=await api('/api/growth?'+buildListParams(requestedFilters,state.offset),{signal:controller.signal});if(request!==state.listRequest)return;state.payload=payload||{};state.items=safeItems(payload);state.total=Math.max(0,numeric(payload?.total)||0);replaceStores(payload?.stores);const matched=state.items.find(item=>String(item?.product?.id||'')===String(selectedId));state.selected=matched||null;state.market=null;state.watchlist=matched?.watchlist||null;updateLinks();renderTermsSummary();renderKpis();renderList();renderPager();renderDetail();$('growth-period').textContent=payload?.period?.from&&payload?.period?.to?`Период ${payload.period.from} — ${payload.period.to} · сформировано ${dateTime(payload.generatedAt)}`:`Сформировано ${dateTime(payload?.generatedAt)}`;if(matched)Promise.allSettled([loadEvidence(matched),loadWatchlist(matched)]);if(payload?.coverage?.competitorMonitoring!==true)announce(payload?.coverage?.message||'Мониторинг всех конкурентов не подключён. Добавляйте локальные наблюдения вручную.')}catch(error){if(error.name==='AbortError'||request!==state.listRequest)return;state.items=[];state.total=0;state.selected=null;renderTermsSummary();renderKpis();renderList();renderPager();renderDetail();announce('Не удалось загрузить центр роста: '+error.message,true)}finally{if(request===state.listRequest){state.controller=null;$('growth-refresh').disabled=false}}}
function addEvidenceCompetitor(values={}){if($('competitor-list').children.length>=5)return;const node=$('competitor-template').content.firstElementChild.cloneNode(true);node.querySelector('[name=competitorName]').value=values.name||'';node.querySelector('[name=competitorUrl]').value=values.url||'';node.querySelector('[name=competitorPrice]').value=values.buyerPrice??'';node.querySelector('[name=competitorUnits]').value=values.unitCount??1;node.querySelector('[name=competitorPosition]').value=values.position??'';node.querySelector('.competitor-remove').addEventListener('click',()=>node.remove());$('competitor-list').append(node)}
function openEvidence(){const item=state.selected;if(!item||$('evidence-dialog').open)return;const dialog=$('evidence-dialog'),evidence=item.marketEvidence||{},latest=evidence.latest||{},generation=++state.dialogGeneration;state.evidenceContext=createDialogContext({storeId:item.product?.storeId,productId:item.product?.id,revision:evidence.revision},generation);$('evidence-form').reset();$('evidence-product').textContent=item.product?.name||'Товар';$('evidence-form').elements.observedAt.value=moscowLocalValue();$('evidence-form').elements.region.value=latest.region||'';$('evidence-form').elements.query.value=latest.query||item.product?.name||'';$('evidence-form').elements.ownBuyerPrice.value=item.price?.customerPrice??latest.ownBuyerPrice??'';$('evidence-form').elements.ownUnitCount.value=latest.ownUnitCount||1;$('competitor-list').replaceChildren();for(const value of Array.isArray(latest.competitors)?latest.competitors.slice(0,5):[])addEvidenceCompetitor(value);if(!$('competitor-list').children.length)addEvidenceCompetitor();$('evidence-error').textContent='';dialog.showModal()}
function evidenceFields(){const fields=$('evidence-form').elements,competitors=[...$('competitor-list').querySelectorAll('.competitor-card')].map(card=>({name:card.querySelector('[name=competitorName]').value,url:card.querySelector('[name=competitorUrl]').value,buyerPrice:card.querySelector('[name=competitorPrice]').value,unitCount:card.querySelector('[name=competitorUnits]').value,position:card.querySelector('[name=competitorPosition]').value}));return {observedAt:fields.observedAt.value,region:fields.region.value,query:fields.query.value,ownBuyerPrice:fields.ownBuyerPrice.value,ownUnitCount:fields.ownUnitCount.value,ownPosition:fields.ownPosition.value,comparable:fields.comparable.checked,competitors}}
async function saveEvidence(event){event.preventDefault();const formNode=$('evidence-form'),context=state.evidenceContext;if(!context||!formNode.reportValidity())return;const fields=evidenceFields();if(!fields.competitors.length){$('evidence-error').textContent='Добавьте хотя бы один аналог.';return}if(fields.competitors.some(value=>!validOzonProductUrl(value.url))){$('evidence-error').textContent='Ссылка аналога должна вести на https://ozon.ru/product/…';return}const signature=JSON.stringify(fields),payload=stableSubmission(context,signature,()=>buildEvidencePayload(fields,{storeId:context.storeId,productId:context.productId,revision:context.revision,commandId:crypto.randomUUID()}));if(!payload.observation.observedAt){$('evidence-error').textContent='Проверьте дату и время наблюдения.';return}const save=$('evidence-save');save.disabled=true;$('evidence-error').textContent='';try{const result=await api('/api/growth/evidence',{method:'POST',body:JSON.stringify(payload)});if(state.evidenceContext!==context||!isCurrentSelection(state,context.storeId,context.productId))return;state.selected.marketEvidence=result;save.disabled=false;$('evidence-dialog').close();renderDetail();await loadList({preserveProductId:context.productId})}catch(error){if(state.evidenceContext===context)$('evidence-error').textContent=error.message}finally{if(state.evidenceContext===context)save.disabled=false}}
function addWatchItem(value={}){if($('watchlist-rows').children.length>=50)return;const node=$('watchlist-template').content.firstElementChild.cloneNode(true);node._growthOriginal=structuredClone(value);node.querySelector('[name=watchName]').value=value.name||'';node.querySelector('[name=watchUrl]').value=value.url||'';node.querySelector('[name=watchStatus]').value=value.matchStatus||'candidate';node.querySelector('[name=watchUnits]').value=value.unitCount??'';node.querySelector('[name=watchNotes]').value=value.matchNotes||'';const metrics=value.metrics;node.querySelector('.watch-metrics').textContent=metrics?`Средняя цена ${money(metrics.averagePrice)} · заказы ${count(metrics.orderedUnits)} · ДРР ${percent(metrics.drrPct)} за ${metrics.periodFrom||'—'}—${metrics.periodTo||'—'}`:'Средние показатели не загружены.';const initialText=node.querySelector('.watch-metrics').textContent;node.querySelector('[name=watchUrl]').addEventListener('input',()=>{node.querySelector('.watch-metrics').textContent=watchProductId(node.querySelector('[name=watchUrl]').value)===watchProductId(value.url)?initialText:'Другая карточка: прежние показатели не будут перенесены.'});node.querySelector('.competitor-remove').addEventListener('click',()=>node.remove());$('watchlist-rows').append(node)}
function openWatchlist(){const item=state.selected;if(!item||$('watchlist-dialog').open)return;const generation=++state.dialogGeneration;state.watchContext=createDialogContext({storeId:item.product?.storeId,productId:item.product?.id,revision:state.watchlist?.revision||item.watchlist?.revision},generation);$('watchlist-product').textContent=item.product?.name||'Товар';$('watchlist-error').textContent='';$('watchlist-rows').replaceChildren();for(const value of Array.isArray(state.watchlist?.competitors)?state.watchlist.competitors:[])addWatchItem(value);if(!$('watchlist-rows').children.length)addWatchItem();$('watchlist-dialog').showModal()}
function watchValues(){return [...$('watchlist-rows').querySelectorAll('.watchlist-card')].map(card=>watchCompetitorInput({name:card.querySelector('[name=watchName]').value,url:card.querySelector('[name=watchUrl]').value,matchStatus:card.querySelector('[name=watchStatus]').value,matchNotes:card.querySelector('[name=watchNotes]').value,unitCount:card.querySelector('[name=watchUnits]').value},card._growthOriginal))}
async function saveWatchlist(event){event.preventDefault();const context=state.watchContext;if(!context)return;const competitors=watchValues(),error=validateWatchlist(competitors);if(error){$('watchlist-error').textContent=error;return}const signature=JSON.stringify(competitors),payload=stableSubmission(context,signature,()=>({storeId:context.storeId,productId:context.productId,expectedRevision:context.revision,commandId:crypto.randomUUID(),competitors})),button=$('watchlist-save');button.disabled=true;try{const result=await api('/api/growth/watchlist',{method:'POST',body:JSON.stringify(payload)});if(state.watchContext!==context||!isCurrentSelection(state,context.storeId,context.productId))return;state.watchlist=result;button.disabled=false;$('watchlist-dialog').close();renderDetail();await loadWatchlist(state.selected)}catch(errorValue){if(state.watchContext===context)$('watchlist-error').textContent=errorValue.message}finally{if(state.watchContext===context)button.disabled=false}}
let searchTimer;form.addEventListener('input',event=>{if(event.target.name!=='search')return;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.offset=0;loadList()},300)});form.addEventListener('change',event=>{if(event.target.name==='search')return;state.offset=0;if(event.target.name==='store'){state.storeId=event.target.value;localStorage.setItem('pult.growth.store',state.storeId);const url=new URL(location.href);state.storeId?url.searchParams.set('store',state.storeId):url.searchParams.delete('store');history.replaceState(null,'',url);updateLinks()}loadList()});form.addEventListener('submit',event=>event.preventDefault());$('growth-refresh').addEventListener('click',()=>loadList({preserveProductId:state.selected?.product?.id}));$('growth-prev').addEventListener('click',()=>{if(state.offset>0){state.offset=Math.max(0,state.offset-LIMIT);loadList()}});$('growth-next').addEventListener('click',()=>{if(state.offset+LIMIT<state.total){state.offset+=LIMIT;loadList()}});$('add-competitor').addEventListener('click',()=>addEvidenceCompetitor());$('evidence-close').addEventListener('click',()=>$('evidence-dialog').close());$('evidence-cancel').addEventListener('click',()=>$('evidence-dialog').close());$('evidence-form').addEventListener('submit',saveEvidence);$('add-watchlist').addEventListener('click',()=>addWatchItem());$('watchlist-close').addEventListener('click',()=>$('watchlist-dialog').close());$('watchlist-cancel').addEventListener('click',()=>$('watchlist-dialog').close());$('watchlist-form').addEventListener('submit',saveWatchlist);
$('evidence-dialog').addEventListener('close',()=>{state.evidenceContext=null;$('evidence-save').disabled=false});
$('watchlist-dialog').addEventListener('close',()=>{state.watchContext=null;$('watchlist-save').disabled=false});
